int main() {
    static char buf[1 << 15];
    long line = 0;
    printf("0 init |"); dump(); printf("\n");
    while (fgets(buf, sizeof buf, stdin)) {
        line++;
        static char *tok[1024];
        int nt = 0;
        for (char *p = strtok(buf, " \n"); p && nt < 1024; p = strtok(nullptr, " \n")) tok[nt++] = p;
        if (nt < 1) { fprintf(stderr, "bad input line %ld\n", line); return 1; }
        set_inputs(tok + nt - 0);
        printf("%ld %s", line, tok[0]);
        if (!strcmp(tok[0], "hal_scheduler.micros64")) {
            uint64_t r = hal_scheduler.micros64();
            tu((unsigned long long)(r));
        } else if (!strcmp(tok[0], "hal_scheduler.feed")) {
            uint16_t a0 = (uint16_t)strtoull(tok[1], nullptr, 10);
            bool a1 = (atoi(tok[2]) != 0);
            float a2 = in_f32(tok[3]);
            hal_scheduler.feed(a0, a1, a2);
        } else if (!strcmp(tok[0], "hal_scheduler.has_sample")) {
            bool r = hal_scheduler.has_sample();
            tb(r);
        } else if (!strcmp(tok[0], "hal_scheduler.sample")) {
            float r = hal_scheduler.sample();
            tf(r);
        } else if (!strcmp(tok[0], "hal_scheduler.delay_microseconds")) {
            uint16_t a0 = (uint16_t)strtoull(tok[1], nullptr, 10);
            hal_scheduler.delay_microseconds(a0);
        } else if (!strcmp(tok[0], "hal_scheduler.delay")) {
            uint16_t a0 = (uint16_t)strtoull(tok[1], nullptr, 10);
            hal_scheduler.delay(a0);
        } else if (!strcmp(tok[0], "hal_scheduler.pending")) {
            uint16_t r = hal_scheduler.pending();
            tu((unsigned long long)(r));
        } else if (!strcmp(tok[0], "hal_scheduler.exhausted")) {
            bool r = hal_scheduler.exhausted();
            tb(r);
        } else if (!strcmp(tok[0], "barometer.copy")) {
            uint8_t a0 = (uint8_t)strtoull(tok[1], nullptr, 10);
            float a1 = in_f32(tok[2]);
            barometer.copy(a0, a1);
        } else if (!strcmp(tok[0], "barometer.update")) {
            barometer.update();
        } else if (!strcmp(tok[0], "barometer.register_sensor")) {
            uint8_t r = barometer.register_sensor();
            tu((unsigned long long)(r));
        } else if (!strcmp(tok[0], "barometer.init")) {
            barometer.init();
        } else if (!strcmp(tok[0], "barometer.healthy")) {
            bool r = barometer.healthy();
            tb(r);
        } else if (!strcmp(tok[0], "barometer.calibrate")) {
            barometer.calibrate();
        } else if (!strcmp(tok[0], "barometer.ground")) {
            float r = barometer.ground();
            tf(r);
        } else if (!strcmp(tok[0], "barometer.failed")) {
            bool r = barometer.failed();
            tb(r);
        } else { printf(" ?"); }
        printf(" |"); dump(); printf("\n");
    }
    return 0;
}
